const PEND = "[PENDING – run test]";

const q = (env, acct, what, input = "<exact input from the table above>") => [
  `Postman, environment **IntelliWMS-${env}**; run "Login" as **${acct}**.`,
  `Open "Chat – POST {{baseUrl}}/query", Body → raw JSON {"message": "${input}"} → Send.`,
  `Capture: ${what}.`,
];
const json = (file, fields) => [
  `Open **${file}** in VS Code (it is the evidence recorded by the original audit run).`,
  `Use Ctrl+F to find ${fields}; make sure the test input and the response are both visible.`,
  "Capture the editor window with the file path visible in the tab.",
];
const ans = "HTTP status, the full response text, routing.rule_id and routing.domain";
/* BEFORE code did not route these compliance questions to the Knowledge agent, so call it directly */
const kb = (env, what, input = "<exact input from the table above>") => [
  `Postman, environment **IntelliWMS-${env}**. (In the BEFORE code this question did not reach the Knowledge agent through /query, so call the Knowledge service directly.)`,
  `New request POST {{kbUrl}}/query, Authorization: No Auth, Body {"query": "${input}", "user_role": "staff"} → Send.`,
  `Capture: ${what}.`,
];
