function outcomeCounts(which) {
  const c = { Pass: 0, Partial: 0, Fail: 0, "Not run": 0 };
  TESTS.forEach((t) => {
    const part = t.outcome.split(" · ").find((x) => x.startsWith(which + ":")) || "";
    const m = part.match(/(Pass|Partial|Fail|Not run)/);
    if (m) c[m[1]] += 1;
  });
  return c;
}

